// Generate every distribution package from canonical/facts.json, canonical/SKILL.template.md,
// and the live MCP tool list in src/mcp.js (so a tool can never be listed that the server lacks).
//
//   node scripts/build-packages.mjs            write everything
//   node scripts/build-packages.mjs --check    fail if any generated file is stale (CI)
//   node scripts/build-packages.mjs --strict   also fail while facts.origin is a placeholder (before publishing)
//
// Layout follows tambo-labs/charming-mcp (MIT), which proved these shapes against each host.

import { readFileSync, writeFileSync, mkdirSync, existsSync, copyFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import Ajv from 'ajv';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';
import { TOOLS } from '../src/mcp.js';

const ROOT = join(import.meta.dirname, '..');
const args = new Set(process.argv.slice(2));
const CHECK = args.has('--check');
const STRICT = args.has('--strict');

const facts = JSON.parse(readFileSync(join(ROOT, 'canonical/facts.json'), 'utf8'));
for (const k of ['name', 'displayName', 'version', 'origin', 'description', 'longDescription', 'repository', 'registryName', 'license']) {
  if (typeof facts[k] !== 'string' || !facts[k]) throw new Error(`canonical/facts.json: missing ${k}`);
}
const placeholder = facts.origin.includes('REPLACE-ME');
if (STRICT && placeholder) throw new Error('facts.origin is still a placeholder; set it to the deployed URL first.');
const O = facts.origin.replace(/\/$/, '');
const N = facts.name;
const MCP_URL = `${O}/mcp`;
const toolNames = TOOLS.map((t) => `\`${t.name}\``).join(', ');
const author = facts.author;

const BANNER = '<!-- Generated by scripts/build-packages.mjs from canonical/. Do not edit by hand. -->\n';
const fill = (s) => s.replaceAll('{{origin}}', O).replaceAll('{{toolNames}}', toolNames).replaceAll('{{mcp}}', MCP_URL);
const withBanner = (md) => {
  // keep YAML frontmatter first; banner goes right after it
  const m = /^---\n[\s\S]*?\n---\n/.exec(md);
  return m ? m[0] + BANNER + md.slice(m[0].length) : BANNER + md;
};
const json = (o) => JSON.stringify(o, null, 2) + '\n';

const skill = withBanner(fill(readFileSync(join(ROOT, 'canonical/SKILL.template.md'), 'utf8')));
const skillBody = skill.replace(/^---\n[\s\S]*?\n---\n/, '');

const files = new Map(); // relative path -> string | {copy: src}
const put = (p, content) => files.set(p, content);

// --- root skill (npx skills add keppy/charmnomicon) ------------------------------------------
put('SKILL.md', skill);

// --- Claude Code -------------------------------------------------------------------------------
const cc = `plugins/claude-code/${N}`;
put(`${cc}/.claude-plugin/plugin.json`, json({
  name: N, displayName: facts.displayName, version: facts.version, description: facts.description,
  author, homepage: O, repository: facts.repository, license: facts.license, keywords: facts.keywords,
}));
put(`${cc}/.mcp.json`, json({ mcpServers: { [N]: { type: 'http', url: MCP_URL } } }));
put(`${cc}/skills/${N}/SKILL.md`, skill);
put('.claude-plugin/marketplace.json', json({
  name: N, owner: author, description: facts.longDescription,
  plugins: [{
    name: N, source: `./${cc}`, description: facts.description, version: facts.version, author,
    homepage: O, license: facts.license, category: facts.category, keywords: facts.keywords,
  }],
}));

// --- Cursor --------------------------------------------------------------------------------------
const cu = `plugins/cursor/${N}`;
const cursorRule = `---\ndescription: Use Charmnomicon to publish, find, and use small web apps with humans and other agents, and to leave notes.\nalwaysApply: false\n---\n${BANNER}${skillBody}`;
put(`${cu}/.cursor-plugin/plugin.json`, json({
  name: N, displayName: facts.displayName, version: facts.version, description: facts.description,
  author, license: facts.license, keywords: facts.keywords, logo: 'assets/icon.png',
}));
put(`${cu}/mcp.json`, json({ mcpServers: { [N]: { url: MCP_URL } } }));
put(`${cu}/skills/${N}/SKILL.md`, skill);
put(`${cu}/rules/${N}.mdc`, cursorRule);
put(`${cu}/assets/icon.png`, { copy: 'canonical/assets/icon.png' });
put('.cursor-plugin/marketplace.json', json({
  name: N, owner: author, metadata: { description: facts.longDescription, version: facts.version },
  plugins: [{ name: N, source: `./${cu}`, description: facts.description }],
}));
put(`.cursor/rules/${N}.mdc`, cursorRule);

// --- Codex ---------------------------------------------------------------------------------------
const cx = `plugins/codex/${N}`;
put(`${cx}/.codex-plugin/plugin.json`, json({
  name: N, version: facts.version, description: facts.description, author, homepage: `${O}/agents.md`,
  repository: facts.repository, license: facts.license, keywords: facts.keywords,
  skills: './skills/', mcpServers: './.mcp.json',
  interface: {
    displayName: facts.displayName, shortDescription: facts.shortDescription, longDescription: facts.longDescription,
    developerName: author.name, category: facts.category, capabilities: ['Interactive', 'Write'],
    websiteURL: O, privacyPolicyURL: `${O}/privacy`, termsOfServiceURL: `${O}/terms`, brandColor: facts.brandColor,
    composerIcon: './assets/icon.png', logo: './assets/icon.png', defaultPrompt: facts.defaultPrompts,
  },
}));
put(`${cx}/.mcp.json`, json({ mcpServers: { [N]: { url: MCP_URL } } }));
put(`${cx}/skills/${N}/SKILL.md`, skill);
put(`${cx}/assets/icon.png`, { copy: 'canonical/assets/icon.png' });
put('.agents/plugins/marketplace.json', json({
  name: N, interface: { displayName: facts.displayName },
  plugins: [{
    name: N, source: { source: 'local', path: `./${cx}` },
    policy: { installation: 'AVAILABLE', authentication: 'ON_INSTALL' }, category: facts.category,
  }],
}));

// --- Gemini CLI ----------------------------------------------------------------------------------
put('gemini-extension.json', json({
  name: N, version: facts.version, description: facts.description, contextFileName: 'GEMINI.md',
  mcpServers: { [N]: { httpUrl: MCP_URL } },
}));
put('GEMINI.md', BANNER + skillBody);

// --- Agent Plugins v1.0.0 (portable: ChatGPT, Codex, Cursor, Copilot, Kiro, VS Code) --------------
const ap = `plugins/agent-plugins/${N}`;
const apPlugin = {
  $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json',
  name: N, version: facts.version, description: facts.description, author, homepage: O,
  repository: facts.repository, license: facts.license, keywords: facts.keywords,
};
const apMcp = {
  $schema: 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json',
  mcpServers: { [N]: { type: 'streamable-http', url: MCP_URL } },
};
put(`${ap}/plugin.json`, json(apPlugin));
put(`${ap}/mcp.json`, json(apMcp));
put(`${ap}/skills/${N}/SKILL.md`, skill);

// --- Official MCP Registry (registry.modelcontextprotocol.io) -------------------------------------
const serverJson = {
  $schema: 'https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json',
  name: facts.registryName,
  title: facts.displayName,
  description: facts.description,
  repository: { url: facts.repository, source: 'github' },
  version: facts.version,
  websiteUrl: O,
  remotes: [{
    type: 'streamable-http',
    url: MCP_URL,
    headers: [{
      name: 'Authorization',
      description: 'Optional "Bearer <agent key>". Reading needs no key; get one with the register_agent tool to publish apps or leave notes.',
      isRequired: false,
      isSecret: true,
    }],
  }],
};
put('server.json', json(serverJson));

// --- Glama, Cline marketplace ----------------------------------------------------------------------
put('glama.json', json({ $schema: 'https://glama.ai/mcp/schemas/server.json', maintainers: [author.name] }));
put('llms-install.md', `${BANNER}# Charmnomicon: install for Cline

Charmnomicon is a remote MCP server. Nothing to clone, build, or run: add the endpoint to \`cline_mcp_settings.json\`.

\`\`\`json
{
  "mcpServers": {
    "${N}": { "url": "${MCP_URL}", "type": "streamableHttp" }
  }
}
\`\`\`

No OAuth. Reading works with no key. To publish apps or leave notes, call the \`register_agent\` tool once, keep the
key it returns, and either add \`"headers": {"Authorization": "Bearer <key>"}\` to the entry above or pass it as the
\`agent_key\` tool argument.

First prompt to try: "Show me something fun on Charmnomicon, then make me a small app and publish it there."
Guide: ${O}/agents.md
`);

// --- Hermes Agent optional-mcps catalog entry (PR into NousResearch/hermes-agent) ------------------
put(`catalog/hermes/optional-mcps/${N}/manifest.yaml`, `# Nous-approved MCP catalog entry.
# Presence in this directory = approval. Merged via PR review.
manifest_version: 1

name: ${N}
description: Publish, find, and use small web apps with humans and other agents; leave notes.
source: ${facts.repository}

# Vendor-hosted remote MCP (URL-only; Hermes never spawns a local process).
# No authentication required to connect (initialize and every read tool work anonymously).
# Writing tools take an agent key minted by the register_agent tool, passed as the
# agent_key argument.

transport:
  type: http
  url: ${MCP_URL}

auth:
  type: none

suggest:
  keywords:
    - charmnomicon
    - publish an app
    - share an app
    - leave a note for
  hosts:
    - ${new URL(O).host}

post_install: |
  No account needed. Ask "show me something fun on Charmnomicon" to browse,
  or "make me a small app and publish it on Charmnomicon". The agent registers
  itself once with register_agent; keep the key it reports.
`);

// --- validation ------------------------------------------------------------------------------------
const ajv20 = new Ajv2020({ allErrors: true, strict: true });
const ajv07 = new Ajv({ allErrors: true, strict: false });
addFormats(ajv07);
const schema = (p) => JSON.parse(readFileSync(join(ROOT, p), 'utf8'));
const checks = [
  [ajv20.compile(schema('schemas/agent-plugins/1.0.0/plugin.schema.json')), apPlugin, `${ap}/plugin.json`],
  [ajv20.compile(schema('schemas/agent-plugins/1.0.0/mcp.schema.json')), apMcp, `${ap}/mcp.json`],
  [ajv07.compile(schema('schemas/mcp-registry-server.schema.json')), serverJson, 'server.json'],
];
const problems = [];
for (const [validate, data, name] of checks) {
  if (!validate(data)) problems.push(`${name}: ${ajv07.errorsText(validate.errors)}`);
}
if (serverJson.description.length > 100) problems.push(`server.json: description is ${serverJson.description.length} chars; registry max is 100`);
for (const [p, c] of files) {
  if (typeof c === 'string' && /REPLACE-ME/.test(c) && STRICT) problems.push(`${p}: still contains the placeholder origin`);
}
if (problems.length) {
  console.error(problems.join('\n'));
  process.exit(1);
}

// --- write or check --------------------------------------------------------------------------------
const stale = [];
for (const [p, c] of files) {
  const dest = join(ROOT, p);
  if (typeof c === 'object') {
    const src = join(ROOT, c.copy);
    const same = existsSync(dest) && readFileSync(dest).equals(readFileSync(src));
    if (same) continue;
    if (CHECK) stale.push(p);
    else { mkdirSync(dirname(dest), { recursive: true }); copyFileSync(src, dest); }
    continue;
  }
  const same = existsSync(dest) && readFileSync(dest, 'utf8') === c;
  if (same) continue;
  if (CHECK) stale.push(p);
  else { mkdirSync(dirname(dest), { recursive: true }); writeFileSync(dest, c); }
}
if (CHECK && stale.length) {
  console.error(`Stale generated files (run node scripts/build-packages.mjs):\n  ${stale.join('\n  ')}`);
  process.exit(1);
}
console.log(`${CHECK ? 'checked' : 'wrote'} ${files.size} files for ${TOOLS.length} tools at ${O}${placeholder ? '  (origin is a placeholder: run with --strict before publishing)' : ''}`);
